def nnbhw(board, colors, x, y):
    # Define the shapes and their relative positions
    shapes = ['nut', 'nut', 'bridge-h', 'washer']
    colors_list = colors
    # Relative offsets for each shape from the reference point (x, y)
    offsets = [(0, 0), (0, 1), (0, 0), (0, 0)]

    # Place each shape with its corresponding color and offset
    for i, (shape, color, (dx, dy)) in enumerate(zip(shapes, colors_list, offsets)):
        if shape == 'bridge-h':
            # Special handling for bridge-h which spans two cells
            put(board, 'bridge-h', color, x + dx, y + dy)
        else:
            put(board, shape, color, x + dx, y + dy)

